-- NEXUS TravelTech PostgreSQL 18 foundation. Run against an empty nexus_traveltech database.
CREATE TABLE early_access_leads (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,email VARCHAR(190) NOT NULL UNIQUE,role VARCHAR(40) NOT NULL,language CHAR(2) NOT NULL DEFAULT 'tr',currency CHAR(3) NOT NULL DEFAULT 'TRY',ip_address INET NULL,user_agent VARCHAR(255),consent_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE suppliers (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,company_name VARCHAR(190) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pilot','active','suspended')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE supplier_users (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,full_name VARCHAR(190) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(30) NOT NULL DEFAULT 'owner',last_login_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE properties (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,property_type VARCHAR(30) NOT NULL,name VARCHAR(190) NOT NULL,city VARCHAR(100),country_code CHAR(2) NOT NULL DEFAULT 'TR',product_details JSONB NOT NULL DEFAULT '{}'::jsonb,duplicate_key CHAR(64),status VARCHAR(16) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_property_supplier_status ON properties(supplier_id,status);
CREATE UNIQUE INDEX uq_properties_duplicate_key ON properties(duplicate_key) WHERE duplicate_key IS NOT NULL;
CREATE TABLE room_types (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,property_id BIGINT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,name VARCHAR(190) NOT NULL,capacity_adults SMALLINT NOT NULL DEFAULT 2 CHECK(capacity_adults BETWEEN 1 AND 20),total_units INTEGER NOT NULL DEFAULT 0 CHECK(total_units>=0),room_details JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE rate_plans (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,property_id BIGINT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,name VARCHAR(190) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'EUR',board_type VARCHAR(50) NOT NULL,cancellation_policy TEXT,status VARCHAR(16) NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE inventory_calendar (room_type_id BIGINT NOT NULL REFERENCES room_types(id) ON DELETE CASCADE,rate_plan_id BIGINT NOT NULL REFERENCES rate_plans(id) ON DELETE CASCADE,stay_date DATE NOT NULL,allotment INTEGER NOT NULL DEFAULT 0,sold INTEGER NOT NULL DEFAULT 0 CHECK(sold>=0),base_price NUMERIC(12,2) NOT NULL DEFAULT 0,min_stay SMALLINT NOT NULL DEFAULT 1,stop_sale BOOLEAN NOT NULL DEFAULT false,PRIMARY KEY(room_type_id,rate_plan_id,stay_date));
CREATE INDEX idx_inventory_date ON inventory_calendar(stay_date,room_type_id);
CREATE TABLE supplier_bookings (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL REFERENCES suppliers(id),property_id BIGINT REFERENCES properties(id),booking_reference VARCHAR(80) NOT NULL UNIQUE,status VARCHAR(24) NOT NULL,check_in DATE,check_out DATE,total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,currency CHAR(3) NOT NULL DEFAULT 'EUR',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_booking_supplier_dates ON supplier_bookings(supplier_id,check_in,check_out);
CREATE TABLE ai_insights (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,insight_type VARCHAR(40) NOT NULL,priority VARCHAR(12) NOT NULL,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'new',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE property_media (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,property_id BIGINT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,room_type_id BIGINT REFERENCES room_types(id) ON DELETE SET NULL,media_scope VARCHAR(20) NOT NULL DEFAULT 'property',file_path TEXT NOT NULL,file_name VARCHAR(255) NOT NULL,mime_type VARCHAR(100) NOT NULL,title VARCHAR(190),description TEXT,alt_text VARCHAR(255),content_hash CHAR(64),is_cover BOOLEAN NOT NULL DEFAULT false,sort_order INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_property_media_scope ON property_media(property_id,media_scope,room_type_id);
CREATE INDEX idx_property_media_content_hash ON property_media(content_hash) WHERE content_hash IS NOT NULL;
CREATE TABLE property_content_translations (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,property_id BIGINT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,entity_type VARCHAR(20) NOT NULL,entity_id BIGINT NOT NULL DEFAULT 0,locale CHAR(2) NOT NULL,field_key VARCHAR(60) NOT NULL,value TEXT NOT NULL,source_locale CHAR(2) NOT NULL DEFAULT 'tr',translation_source VARCHAR(20) NOT NULL DEFAULT 'manual',updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(property_id,entity_type,entity_id,locale,field_key));
CREATE INDEX idx_content_translation_lookup ON property_content_translations(property_id,entity_type,entity_id,locale);
CREATE TABLE ai_provider_settings (provider VARCHAR(32) PRIMARY KEY,encrypted_api_key TEXT,model VARCHAR(80) NOT NULL DEFAULT 'deepseek-chat',updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE platform_settings (setting_key VARCHAR(100) PRIMARY KEY,value JSONB NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_type_catalog (code VARCHAR(40) PRIMARY KEY,label VARCHAR(120) NOT NULL,unit VARCHAR(120) NOT NULL,steps JSONB NOT NULL DEFAULT '[]'::jsonb,fields JSONB NOT NULL DEFAULT '[]'::jsonb,room_setup BOOLEAN NOT NULL DEFAULT false,hint TEXT NOT NULL DEFAULT '',is_active BOOLEAN NOT NULL DEFAULT true,sort_order SMALLINT NOT NULL DEFAULT 100,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE product_verification_requirements (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,product_type_code VARCHAR(40) NOT NULL REFERENCES product_type_catalog(code) ON DELETE CASCADE,requirement_code VARCHAR(60) NOT NULL,label VARCHAR(190) NOT NULL,is_required BOOLEAN NOT NULL DEFAULT true,sort_order SMALLINT NOT NULL DEFAULT 100,UNIQUE(product_type_code,requirement_code));
INSERT INTO platform_settings(setting_key,value) VALUES ('gemini_visual_similarity_threshold','90'::jsonb),('gemini_auto_pause_duplicate','true'::jsonb),('kps_identity_verification_enabled','false'::jsonb),('admin_alert_email','""'::jsonb);
CREATE TABLE supplier_verifications (supplier_id BIGINT PRIMARY KEY REFERENCES suppliers(id) ON DELETE CASCADE,legal_identity_type VARCHAR(20) NOT NULL DEFAULT 'company' CHECK (legal_identity_type IN ('individual','company')),legal_name VARCHAR(190) NOT NULL DEFAULT '',authority_role VARCHAR(40) NOT NULL DEFAULT '',verification_reference VARCHAR(120),hotel_certificate_number VARCHAR(120),request_note TEXT,requested_product_types JSONB NOT NULL DEFAULT '[]'::jsonb,approved_product_types JSONB NOT NULL DEFAULT '[]'::jsonb,review_status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (review_status IN ('pending','approved','rejected')),identity_status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (identity_status IN ('pending','approved','rejected')),identity_check_status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (identity_check_status IN ('pending','verified','failed','service_error')),identity_check_message VARCHAR(500),identity_checked_at TIMESTAMPTZ,authority_status VARCHAR(16) NOT NULL DEFAULT 'pending' CHECK (authority_status IN ('pending','approved','rejected')),review_note TEXT,reviewed_by VARCHAR(190),submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(),reviewed_at TIMESTAMPTZ);
CREATE INDEX idx_supplier_verification_review ON supplier_verifications(review_status,submitted_at);
CREATE TABLE admin_alerts (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,alert_type VARCHAR(50) NOT NULL,supplier_id BIGINT REFERENCES suppliers(id) ON DELETE CASCADE,title VARCHAR(190) NOT NULL,body TEXT NOT NULL,is_read BOOLEAN NOT NULL DEFAULT false,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_admin_alerts_open ON admin_alerts(is_read,created_at DESC);
CREATE TABLE supplier_verification_documents (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,document_type VARCHAR(50) NOT NULL,file_name VARCHAR(255) NOT NULL,stored_name VARCHAR(100) NOT NULL,mime_type VARCHAR(100) NOT NULL,file_size INTEGER NOT NULL,uploaded_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(supplier_id,document_type));
CREATE INDEX idx_supplier_verification_documents_supplier ON supplier_verification_documents(supplier_id);
CREATE TABLE duplicate_listing_signals (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,property_id BIGINT NOT NULL REFERENCES properties(id) ON DELETE CASCADE,matched_property_id BIGINT REFERENCES properties(id) ON DELETE SET NULL,signal_type VARCHAR(40) NOT NULL,confidence NUMERIC(5,2) NOT NULL DEFAULT 100,details JSONB NOT NULL DEFAULT '{}'::jsonb,status VARCHAR(16) NOT NULL DEFAULT 'open' CHECK (status IN ('open','confirmed','dismissed')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_duplicate_listing_signals_status ON duplicate_listing_signals(status,created_at DESC);
CREATE TABLE audit_logs (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_type VARCHAR(30) NOT NULL,actor_id BIGINT,action VARCHAR(80) NOT NULL,entity_type VARCHAR(50) NOT NULL,entity_id BIGINT,meta JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_audit_logs_entity ON audit_logs(entity_type,entity_id,created_at DESC);
CREATE TABLE supplier_payment_settings (supplier_id BIGINT PRIMARY KEY REFERENCES suppliers(id) ON DELETE CASCADE,virtual_pos_enabled BOOLEAN NOT NULL DEFAULT false,provider_name VARCHAR(120),merchant_name VARCHAR(190),settlement_iban VARCHAR(34),installment_enabled BOOLEAN NOT NULL DEFAULT false,installment_max SMALLINT,pos_status VARCHAR(16) NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE supplier_invoices (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE CASCADE,booking_id BIGINT REFERENCES supplier_bookings(id) ON DELETE SET NULL,invoice_number VARCHAR(80) NOT NULL,invoice_type VARCHAR(20) NOT NULL DEFAULT 'sales',customer_name VARCHAR(190) NOT NULL,customer_tax_number VARCHAR(64),issue_date DATE NOT NULL,due_date DATE,subtotal NUMERIC(12,2) NOT NULL DEFAULT 0,tax_rate NUMERIC(5,2) NOT NULL DEFAULT 20,tax_amount NUMERIC(12,2) NOT NULL DEFAULT 0,total_amount NUMERIC(12,2) NOT NULL DEFAULT 0,currency CHAR(3) NOT NULL DEFAULT 'TRY',status VARCHAR(16) NOT NULL DEFAULT 'draft',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(supplier_id,invoice_number));
CREATE TABLE hotel_taxonomies (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,taxonomy_type VARCHAR(20) NOT NULL CHECK(taxonomy_type IN ('property_type','star_rating','theme')),name VARCHAR(120) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT true,sort_order SMALLINT NOT NULL DEFAULT 100,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(taxonomy_type,name));
CREATE TABLE hotel_taxonomy_translations (taxonomy_id BIGINT NOT NULL REFERENCES hotel_taxonomies(id) ON DELETE CASCADE,locale CHAR(2) NOT NULL,name VARCHAR(120) NOT NULL,PRIMARY KEY(taxonomy_id,locale));
