CREATE TABLE sms_packages (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,code VARCHAR(40) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,credit_count INTEGER NOT NULL CHECK(credit_count>0),price_amount NUMERIC(12,2) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'TRY',is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sms_entitlements (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,account_type VARCHAR(16) NOT NULL CHECK(account_type IN ('supplier','agency')),account_id BIGINT NOT NULL,is_enabled BOOLEAN NOT NULL DEFAULT false,credits_remaining INTEGER NOT NULL DEFAULT 0,notification_phone VARCHAR(40),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(account_type,account_id));
CREATE TABLE sms_outbox (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,account_type VARCHAR(16) NOT NULL,account_id BIGINT NOT NULL,phone VARCHAR(40) NOT NULL,message TEXT NOT NULL,related_type VARCHAR(40),related_id BIGINT,status VARCHAR(16) NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','sent','failed','skipped')),provider_message_id VARCHAR(120),error_message TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),sent_at TIMESTAMPTZ);
CREATE INDEX idx_sms_outbox_status ON sms_outbox(status,created_at);
